public class TallyCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Tally impl) {
        try {
            return TallyChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectTally()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectTally()));
        check("rejects the version that remembers only the last number", false, verdict(new LastValueTally()));
        check("rejects the reset that does not reset", false, verdict(new NoResetTally()));
        check("rejects the total() that empties the tally as a side effect", false, verdict(new DrainingTally()));
        check("rejects the version that silently ignores negative numbers", false, verdict(new PositiveOnlyTally()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectTally implements Tally {
    private int total;

    public void add(int n) { total += n; }
    public int total() { return total; }
    public void reset() { total = 0; }
}

class AlsoCorrectTally implements Tally {
    private final java.util.List<Integer> added = new java.util.ArrayList<>();

    public void add(int n) { added.add(n); }
    public int total() {
        int sum = 0;
        for (int n : added) sum += n;
        return sum;
    }
    public void reset() { added.clear(); }
}

class LastValueTally implements Tally {
    private int last;

    public void add(int n) { last = n; }
    public int total() { return last; }
    public void reset() { last = 0; }
}

class NoResetTally implements Tally {
    private int total;

    public void add(int n) { total += n; }
    public int total() { return total; }
    public void reset() { }
}

class DrainingTally implements Tally {
    private int total;

    public void add(int n) { total += n; }
    public int total() {
        int answer = total;
        total = 0;
        return answer;
    }
    public void reset() { total = 0; }
}

class PositiveOnlyTally implements Tally {
    private int total;

    public void add(int n) { if (n > 0) total += n; }
    public int total() { return total; }
    public void reset() { total = 0; }
}

