/**
 * TASK: Write the checks that decide whether a Tally is correct.
 *
 *   A Tally remembers a running total, starting at 0.
 *     add(n)   adds n to the total (n may be negative).
 *     total()  returns the running total and changes nothing.
 *     reset()  puts the total back to 0.
 *   Example: add(3), add(4) -> total() is 7; reset() -> total() is 0.
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
interface Tally {
    /* Provided -- do not edit. */
    void add(int n);
    int total();
    void reset();
}

public class TallyChecker {

    public static boolean isCorrect(Tally impl) {
        try {
            if (impl.total() != 0) return false;

            impl.add(3);
            impl.add(4);
            if (impl.total() != 7) return false;
            if (impl.total() != 7) return false;

            impl.add(-2);
            if (impl.total() != 5) return false;

            impl.reset();
            if (impl.total() != 0) return false;

            impl.add(6);
            if (impl.total() != 6) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
